import torch


def run(input1, input2, target, margin, reduction):
    return torch.ops.aten.margin_ranking_loss(
        input1, input2, target, margin, reduction
    )


def gen_inputs(ctx, device):
    shape = tuple(ctx["target__shape"])
    dtype = getattr(torch, ctx["target__dtype"])
    target = (
        torch.randint(0, 2, shape, device=device, dtype=torch.int8) * 2 - 1
    ).to(dtype)
    return {"target": target}
